// 1. Extract payload from Webhook
const body = $input.first().json.body || $input.first().json;

// 2. Extract inputs with defaults for Lutsk
const scope = body.quiz?.scope || 'whole_flat'; // whole_flat | single_room | engineering
const propertyType = body.quiz?.property_type || 'new'; // new | secondary
const areaM2 = Number(body.quiz?.area_m2) || 50;
const addons = Array.isArray(body.quiz?.addons) ? body.quiz.addons : [];
const district = body.contact?.district || 'м. Луцьк';

// 3. Tariffs & Calculation Matrix for Lutsk Market
let baseCost = 0;
let scopeTitle = '';
let detailTitle = '';

if (scope === 'whole_flat') {
  const repairType = body.quiz?.repair_type || 'capital';
  const flatRates = {
    cosmetic: { title: 'Косметичний під ключ (3 500 грн/м²)', rate: 3500 },
    capital: { title: 'Капітальний під ключ (7 500 грн/м²)', rate: 7500 },
    designer: { title: 'Дизайнерський преміум (13 500 грн/м²)', rate: 13500 }
  };
  const selected = flatRates[repairType] || flatRates.capital;
  const multiplier = propertyType === 'secondary' ? 1.2 : 1.0;
  baseCost = Math.round(areaM2 * selected.rate * multiplier);
  scopeTitle = 'Вся квартира / Будинок';
  detailTitle = `${selected.title} (${areaM2} м², ${propertyType === 'secondary' ? 'вторинка x1.2' : 'новобудова'})`;
} else if (scope === 'single_room') {
  const roomType = body.quiz?.room_type || 'bathroom';
  const roomRates = {
    bathroom: { title: 'Ванна кімната / Санвузол під ключ', cost: 25000 },
    kitchen: { title: 'Кухня під ключ (комунікації + фартух)', cost: 18000 },
    bedroom: { title: `Житлова кімната / Спальня (${areaM2} м²)`, cost: Math.round(areaM2 * 3500) },
    balcony: { title: 'Балкон / Лоджія (утеплення + оздоблення)', cost: 14000 }
  };
  const selected = roomRates[roomType] || roomRates.bathroom;
  baseCost = selected.cost;
  scopeTitle = 'Окреме приміщення';
  detailTitle = selected.title;
} else if (scope === 'engineering') {
  const engType = body.quiz?.engineering_type || 'electric';
  const engRates = {
    electric: { title: 'Повний електромонтаж (щиток, автомати, точки)', cost: 15000 },
    plumbing: { title: 'Сантехніка під ключ (REHAU, інсталяція, фільтри)', cost: 12000 },
    tile: { title: `Укладання керамограніту (${areaM2} м²)`, cost: Math.round(areaM2 * 600) }
  };
  const selected = engRates[engType] || engRates.electric;
  baseCost = selected.cost;
  scopeTitle = 'Спецмонтаж / Інженерія';
  detailTitle = selected.title;
}

// Addons Matrix (Lutsk Edition)
const addonPrices = {
  dismantling: { title: 'Демонтаж та вивіз будсміття по Луцьку', price: 6000 },
  materials_procurement: { title: 'Закупівля матеріалів зі знижкою 20% (Епіцентр)', price: 4000 },
  design_supervision: { title: '3D-візуалізація та розгортка комунікацій', price: 10000 }
};

let addonsTotal = 0;
const addonsNames = [];
addons.forEach(key => {
  if (addonPrices[key]) {
    addonsTotal += addonPrices[key].price;
    addonsNames.push(`${addonPrices[key].title} (+${addonPrices[key].price.toLocaleString('uk-UA')} грн)`);
  }
});

const totalAmount = baseCost + addonsTotal;

// 4. Client & Contact Metadata
const userId = body.user?.id ? String(body.user.id) : '';
const username = body.user?.username ? `@${body.user.username}` : 'Немає юзернейма';
const clientName = body.contact?.name || body.user?.first_name || 'Клієнт';
const clientPhone = body.contact?.phone || 'Не вказано';

// Kyiv Timestamp
const now = new Date();
const timestamp = now.toLocaleString('uk-UA', { timeZone: 'Europe/Kyiv' });

return [{
  json: {
    timestamp,
    userId,
    username,
    clientName,
    clientPhone,
    district,
    scopeTitle,
    detailTitle,
    areaM2,
    addonsTitles: addonsNames.length > 0 ? addonsNames.join(', ') : 'Без додаткових опцій',
    baseCost,
    addonsTotal,
    totalAmount,
    totalFormatted: totalAmount.toLocaleString('uk-UA') + ' грн',
    status: 'Новий лід'
  }
}];

