// Map all read rows to a clean array of leads
const items = $input.all();
const leads = items.map((item, index) => {
  const row = item.json;
  return {
    id: index + 1,
    timestamp: row['Дата/Час'] || '',
    userId: row['User ID'] || '',
    username: row['Username'] || '',
    name: row["Ім'я"] || '',
    phone: row['Телефон'] || '',
    repairType: row['Тип ремонту'] || '',
    propertyType: row['Тип житла'] || '',
    areaM2: row['Площа (м²)'] || '',
    addons: row['Додаткові опції'] || '',
    total: row['Розрахунок (грн)'] || '',
    status: row['Статус'] || 'Новий лід'
  };
}).reverse(); // Latest leads first

return [{
  json: {
    success: true,
    count: leads.length,
    leads: leads
  }
}];

